<label>نوع محدوده جغرافیایی<select name="geo_role"><?php foreach(['residence_at_incident'=>'محل سکونت هنگام واقعه','birth_place'=>'محل تولد','martyrdom_place'=>'محل شهادت','burial_place'=>'محل دفن'] as $role=>$label): ?><option value="<?= $role ?>" <?= ($f['geo_role']??'residence_at_incident')===$role?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></label>
<?php foreach(['country'=>'کشور','province'=>'استان','county'=>'شهرستان','city'=>'شهر'] as $level=>$title):$selected=(string)($f['geo_'.$level]??'');$options=$catalogFilters['geo'][$level]??[]; ?>
<details class="public-axis-filter" <?= $selected!==''?'open':'' ?>><summary><?= $title ?></summary><input type="search" data-filter-search aria-label="جست‌وجو در <?= $title ?>" placeholder="جست‌وجوی گزینه‌ها"><div class="public-filter-options"><label data-filter-option><input type="radio" name="geo_<?= $level ?>" value="" <?= $selected===''?'checked':'' ?>>همه</label><?php foreach($options as $option): ?><label data-filter-option><input type="radio" name="geo_<?= $level ?>" value="<?= $option['id'] ?>" <?= $selected===(string)$option['id']?'checked':'' ?>><span><?= e($option['title']) ?></span></label><?php endforeach ?><?php if(!$options): ?><p class="hint">هنوز مکان منتشرشده‌ای در این سطح ثبت نشده است.</p><?php endif ?></div></details>
